            let initial = battle_state_from_lists(vec![p1], vec![], vec![p2], vec![]);

            let state = first_state(run(&initial, vec![0], vec![0], &move_dex, &pokemon_dex, false, 1));
            assert_eq!(state.p1_active_mons[0].boosts[3], 1); // Sp. Def
