            assert!(no_sand_spit_outcomes.iter().all(|(state, _)| {
                matches!(state, MatchState::BattleState(bs) if bs.weather != Some(Weather::Sandstorm))
            }), "Without SandSpit, Tackle should NOT set Sandstorm");
